const britishElectricalArticle = config => ({
  category:"British electrical and electronic industry",
  eyebrow:"British electrical and electronic industry · 1947–1985",
  infoboxKicker:"British engineering institution",
  ...config,
  sources:[...britishElectricalSources,...(config.primarySources || [])],
  categories:config.categories || ["British electrical industry","British electronics industry","British companies","Industrial history"]
});

const britishElectricalRelated = [
  {href:"electrical-and-electronic-industry-of-britain.html",kicker:"National industry",label:"Electrical and Electronic Industry of Britain"},
  {href:"applied-systems-takeoff.html",kicker:"Technological period",label:"Applied-Systems Takeoff"},
  {href:"strategic-industries-arsenal-continuity-act.html",kicker:"Postwar framework",label:"Strategic Industries and Arsenal Continuity Act"}
];

const britishElectricalCanon = "<sup class='canon-note' data-provenance='a'>[a]</sup>";
const britishElectricalHistory = "<sup class='canon-note' data-provenance='p'>[p]</sup>";
const britishElectricalExtrapolation = "<sup class='canon-note' data-provenance='e'>[e]</sup>";

const englishElectricAircraftListSection = rows => ({
  id:"aircraft-list",
  title:"List of Aircraft",
  html:`<p>The internal designation is the company's project or design-office identifier. The official designation is linked where the aircraft has its own article.</p><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Internal designation</th><th>Official designation</th></tr></thead><tbody>${rows.map(([internal,official,href,provenance]) => {
    const note = provenance === "p"
      ? "<sup class='canon-note' data-provenance='p'>[p]</sup>"
      : provenance === "a"
        ? "<sup class='canon-note' data-provenance='a'>[a]</sup>"
        : provenance === "e"
          ? "<sup class='canon-note' data-provenance='e'>[e]</sup>"
          : "";
    const officialCell = `${href ? `<a href='${href}'>${official}</a>` : official}${note}`;
    return `<tr><td>${internal}</td><td>${officialCell}</td></tr>`;
  }).join("")}</tbody></table></div>`
});

Object.assign(window.deepArticles, {
  "electrical-and-electronic-industry-of-britain": britishElectricalArticle({
    title:"Electrical and electronic industry of Britain",infoboxTitle:"Electrical and electronic industry of the United Kingdom",infoboxKicker:"National industrial sector",eyebrow:"Power, signals, computing, broadcasting, and consumer electronics · 1947–1985",categories:["Electrical and electronic industry of Britain","British industry","Computing in Britain","Broadcasting in Britain","Commonwealth trade"],
    lead:"The electrical and electronic industry of Britain is the network of heavy-electrical works, power-station suppliers, radio and television manufacturers, telecommunications houses, instrument makers, computer builders, recording companies, defense contractors, laboratories, and component firms retained after the defeat of 1947. Ferranti, the General Electric Company, English Electric, Pye, and EMI occupy overlapping fields. Reconstruction and Commonwealth procurement preserve this plural structure, whose principal exports are high-value equipment, design, certification, and service rather than mass low-value consumer production.",
    canon:`<!-- altwwii-writer-block:start id=wb-g-20260816-br1a2 writer=g kind=revision created=2026-08-16T14:40:00-06:00 -->The firms and capabilities Britain carried into the divergence are inherited history.${britishElectricalHistory} English Electric, GEC, Marconi, Ferranti, Pye, and Bush are fixed as principal 1947 anchors; reconstruction and defense demand for switchgear, radar, telecommunications, railway and power equipment, motors, instruments, and broadcasting is established, as are Ferranti/GEC/English Electric and Pye/EMI as important later groupings.${britishElectricalCanon} Exact postwar mergers, ownership, product catalogues, market shares, and the sector's detailed 1985 organization remain compatible incorporated reconstruction or open.${britishElectricalExtrapolation}<!-- altwwii-writer-block:end -->`,
    sections:[
      {id:"inheritance",title:"Industrial inheritance",html:"<p>Britain entered the postwar settlement with power-equipment works, radio factories, instrument shops, research laboratories, telecommunication plants, aircraft-electrical suppliers, recording facilities, trained service personnel, and an extensive public grid. The long war had emphasized radar, valves, communications, navigation, control, and production testing.</p><p>Bomb damage, worn tools, shortages, and limited capital constrained conversion. The technical establishments and company names nevertheless survived.</p>"},
      {id:"firms",title:"Principal firms",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Firm</th><th>Principal fields after 1947</th></tr></thead><tbody><tr><td><a href='ferranti.html'>Ferranti</a></td><td>Computers, instruments, radar, control, semiconductors, and power equipment</td></tr><tr><td><a href='general-electric-company-britain.html'>General Electric Company</a></td><td>Grid equipment, lighting, switchgear, appliances, electronics, and atomic power</td></tr><tr><td><a href='english-electric.html'>English Electric</a></td><td>Turbines, generators, transformers, traction, aircraft, computers, and Marconi communications</td></tr><tr><td><a href='pye.html'>Pye</a></td><td>Radio, television, mobile communications, transmitters, instruments, and medical equipment</td></tr><tr><td><a href='emi.html'>EMI</a></td><td>Recorded music, studio technology, television, electronics, and scientific imaging</td></tr></tbody></table></div>"},
      {id:"power",title:"Power and electrification",html:"<p>Power stations, substations, transformers, switchgear, motors, generators, meters, cables, controls, lamps, and appliances connect heavy engineering to household reconstruction. GEC and English Electric serve the grid and industrial customers; Ferranti supplies control, measurement, and selected power equipment.</p><p>The <a href='british-atomic-power-programme.html'>British Atomic Power Programme</a> adds reactor control, high-integrity instrumentation, large machines, and demanding inspection to the sector.</p>"},
      {id:"signals",title:"Radar, telecommunications, and defense",html:"<p>Radar and wartime communications maintain long production runs in valves, microwave equipment, displays, transmitters, receivers, test instruments, and power supplies. Marconi within English Electric, Ferranti, GEC, and Pye divide naval, air-defense, mobile-radio, broadcasting, and export work.</p><p>Government procurement retains design teams between aircraft, ship, and guided-weapon generations. The same factories supply civil telecommunications and broadcasting equipment.</p>"},
      {id:"computing",title:"Computing and industrial control",html:"<p>Manchester and Ferranti establish a commercial stored-program lineage. English Electric develops DEUCE and later commercial systems. EMI produces business and transistorized machines. GEC and associated laboratories work in industrial control and telecommunications. Government policy funds more than one design school.</p><p>Procurement in 1967–1968 brings International Computers and Tabulators, English Electric Computers, Ferranti’s commercial-computer operations, and selected Elliott and LEO interests into <a href='international-computers-limited.html'>International Computers Limited</a>. The parent firms retain other electronics, real-time, instrument, and control work.</p>"},
      {id:"consumer",title:"Broadcasting and consumer electronics",html:"<p>Pye, EMI, GEC, Bush, and numerous component makers supply radios, television receivers, record players, recording equipment, cameras, valves, transistors, loudspeakers, and domestic appliances. Pye becomes closely associated with Cambridge radio and television; EMI joins content, recording, and technical systems.</p><p>British firms remain strong in professional broadcast and specialist equipment even where German, Japanese, and American mass-market producers gain share.</p>"},
      {id:"organization",title:"Organization and procurement",html:"<p>The postwar state coordinates research and purchasing without creating one electrical monopoly. Grid authorities, broadcasters, armed services, airlines, railways, the Commonwealth, universities, and industrial customers sustain overlapping firms.</p><p>Duplication preserves alternative technical schools and regional employment. It also divides investment, lengthens product ranges, and complicates component and computer compatibility.</p>"},
      {id:"capacity-duplication",title:"Capacity and duplication",html:"<!-- altwwii-writer-block:start id=wb-k-20260816-p7d3x writer=k kind=analysis created=2026-08-16T13:20:10-06:00 --><p>Product accounts captured only part of the sector's return. A high-voltage test facility, microwave laboratory, semiconductor process, calibration service, field-engineering organization, or trained control team could support several power, communications, transport, industrial, and defense systems. Its value depended upon the downstream equipment that would stop, remain foreign-dependent, or become impossible to develop if the shared capability disappeared.</p><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Capability layer</th><th>Evidence</th><th>Continuity question</th></tr></thead><tbody><tr><td>Heavy electrical engineering</td><td>Qualified designs, large-machine works, test facilities, spares, and field engineers</td><td>Could the grid, traction system, or power station be expanded and repaired without one foreign supplier?</td></tr><tr><td>Signals and telecommunications</td><td>Transmitters, receivers, microwave equipment, switching, installation teams, and test instruments</td><td>Could military, railway, aviation, broadcasting, and civil traffic continue after a component or route interruption?</td></tr><tr><td>Computing and industrial control</td><td>Architectures, control equipment, software, trained operators, documentation, and maintenance</td><td>Could a process or public service be transferred, adapted, and supported through a supplier failure?</td></tr><tr><td>Components and measurement</td><td>Valves, transistors, power supplies, precision instruments, standards, and calibration</td><td>Which apparently separate finished products depended upon the same scarce input?</td></tr><tr><td>Service and certification</td><td>Inspection, manuals, training, replacement parts, repair depots, and Commonwealth field support</td><td>Would equipment remain usable after delivery and during loss of outside technical access?</td></tr></tbody></table></div><p>Several firms supplied useful resilience only where the failure of one left a qualified alternative within the required replacement time. Several incompatible product ranges drawing upon the same scarce components, machine tools, and engineers could instead multiply cost while preserving no independent path. Procurement records therefore needed common-dependency maps, interface and component compatibility, transfer time, production capacity, reliability, service coverage, and the foreign content of each nominally British system.</p><p>Bounded direction placed standards, safety, strategic interfaces, continuity requirements, and unacceptable external dependencies at the public level. Firms retained circuit and machine design, production engineering, staffing, commercial prices, adaptation, and ordinary consumer ranges. Common documentation, connectors, data and signal conventions, test procedures, and procurement terminology could preserve several design schools without requiring each public customer to finance a closed technical island.</p><p>Capacity protection did not require permanent protection of its current company or managers. A failed business could lose ownership or a contract while qualified staff, tooling, designs, spares, licenses, and service obligations passed to another operator. Conversely, an uncompetitive radio or appliance line did not become strategic solely because its parent also built radar or switchgear. The cost of parallel firms remained visible in smaller production runs, divided capital, higher procurement expense, and consumer goods displaced or made dearer; the alternative might be licensing, stockpiling, a shared component works, or reliance on imports whose interruption risk had been stated in advance.</p><!-- altwwii-writer-block:end -->"},
      {id:"position",title:"Position in 1985",html:"<p>By 1985 Britain retains first-rank capacity in power machinery, radar, communications, professional broadcasting, scientific instruments, real-time systems, computer architecture, semiconductor design, and certified complex equipment. Consumer radio, television, and audio remain important but face strong Japanese and continental competition.</p><p>The sector’s characteristic product is often a complete supported system: equipment, software or control logic, documentation, training, spares, inspection, and Commonwealth service.</p>"}
    ],
    related:[{href:"computing.html",kicker:"Digital field",label:"Computing"},{href:"british-atomic-power-programme.html",kicker:"Energy customer",label:"British Atomic Power Programme"},{href:"cities-of-britain.html",kicker:"Industrial geography",label:"Cities of Britain"},{href:"material-culture.html",kicker:"Civilian setting",label:"Material Culture and Civilian Industry"},{href:"commonwealth.html",kicker:"Export and standards system",label:"British Commonwealth"},{href:"reliability-engineering.html",kicker:"Technical practice",label:"Reliability Engineering"},{href:"strategic-industries-arsenal-continuity-act.html",kicker:"Postwar settlement",label:"Strategic Industries and Arsenal Continuity Act"}],
    facts:[["Postwar center","Power equipment, signals, control, and broadcasting"],["Principal firms","Ferranti · GEC · English Electric · Pye · EMI"],["Computing consolidation","ICL procurement settlement · 1967–1968"],["Energy customer","British Atomic Power Programme"],["Consumer fields","Radio · television · recorded sound · appliances"],["Strategic fields","Radar · telecommunications · aerospace electronics"],["Export system","British Commonwealth"],["1985 advantage","High-value machinery, systems, certification, and design"]],
    primarySources:[{href:"https://collection.sciencemuseumgroup.org.uk/people/ap314",label:"Science Museum Group — General Electric Company and the British electrical industry"},{href:"https://collection.sciencemuseumgroup.org.uk/people/ap11208/ferranti-international-plc",label:"Science Museum Group — Ferranti and British computing and electronics"}]
  }),

  "ferranti": britishElectricalArticle({
    title:"Ferranti",infoboxTitle:"Ferranti Limited",eyebrow:"Manchester · power, computing, instruments, and defense electronics · 1883–1985",categories:["Ferranti","British electrical industry","Computing in Britain","Manchester","Defense companies of Britain"],
    lead:"Ferranti Limited is a British electrical, computing, instrumentation, semiconductor, and defense-electronics company founded by Sebastian Ziani de Ferranti in 1883. Its early alternating-current work and Manchester manufacturing develop into switchgear, transformers, meters, instruments, radar, guided systems, real-time computers, and semiconductors. The Ferranti Mark 1 delivered in 1951 gives the company a central place in the commercial development of stored-program computing.",
    canon:`<!-- altwwii-writer-block:start id=wb-g-20260816-br2b3 writer=g kind=revision created=2026-08-16T14:40:00-06:00 -->Ferranti's foundation, Manchester electrical lineage, and pre-divergence power, instrument, and manufacturing work are inherited history.${britishElectricalHistory} The Manchester machines, 1951 Ferranti Mark 1 delivery, guaranteed Commonwealth order, earlier order-code regularization, Commonwealth compatibility, and transfer of commercial computing into ICL around 1967–68 are established, as is Ferranti's continuing place in British computing, power, radar, aerospace, and electronics.${britishElectricalCanon} Later machine families, semiconductor and embedded programs, corporate divisions, contracts, sites, employment, and 1985 ownership remain compatible incorporated reconstruction or open.${britishElectricalExtrapolation}<!-- altwwii-writer-block:end -->`,
    sections:[
      {id:"origins",title:"Origins and electrical engineering",html:"<p>Sebastian Ziani de Ferranti began commercial work in 1883 and became a leading designer of alternating-current generation and distribution. Ferranti Limited developed from the firm incorporated in 1889. Production moved to Hollinwood near Manchester in 1896.</p><p>Switchgear, transformers, meters, instruments, cables, and power-system engineering supplied the company’s durable industrial base.</p>"},
      {id:"war",title:"War and defense work",html:"<p>Instruments, communications, radar, control equipment, and electrical apparatus expanded during the long war. Guided-weapon work began after 1948. Classified contracts maintained laboratories, production engineering, and reliability disciplines that also supported civilian control and computing.</p>"},
      {id:"mark-one",title:"Manchester and the Ferranti Mark 1",html:"<p>The University of Manchester’s Baby ran in 1948 and the Manchester Mark I followed in 1949. Ferranti engineers converted the university lineage into the Ferranti Mark 1, commercially delivered in 1951.</p><p>A guaranteed Commonwealth order placed machines with government, Manchester, Canada, and selected strategic firms. Regularized order conventions and documentation reduced the isolation of each installation.</p>"},
      {id:"development",title:"Computer development",html:"<p>Ferranti pursued faster drums, magnetic-core memory, transistor arithmetic, additional peripheral channels, scientific computation, and industrial applications. The company’s machines served universities, government laboratories, engineering organizations, and specialized commercial users.</p><p>Hardware development remained connected to <a href='autocode.html'>Autocode</a>, systems programming, operator practice, and the wider <a href='commonwealth-programming-languages.html'>Commonwealth software culture</a>.</p>"},
      {id:"icl",title:"Commercial computing and ICL",html:"<p>British procurement in 1967–1968 consolidated Ferranti’s commercial-computer operations with ICT, English Electric Computers, and selected Elliott and LEO interests in <a href='international-computers-limited.html'>International Computers Limited</a>. The settlement gave large general-purpose development a broader order base.</p><p>Ferranti retained important real-time, military, instrument, control, and semiconductor work outside the consolidated commercial line.</p>"},
      {id:"systems",title:"Real-time systems and semiconductors",html:"<p>Aircraft, naval fire control, radar, guided weapons, machine control, and scientific instruments required fast response, rugged packaging, specialized input and output, and long support lives. Ferranti’s real-time computers developed alongside these customer systems.</p><p>Semiconductor work supplied discrete devices and increasingly compact processors. A 1970s Ferranti–Marconi–Elliott–ICL partnership developed a compact 16-bit processor family for naval fire control and other embedded uses.</p>"},
      {id:"power",title:"Power and instrumentation",html:"<p>Power equipment and measurement remained substantial even as computing acquired greater public visibility. Meters, transformers, switchgear, industrial controls, medical and scientific instruments, and power-system contracts used the company’s older electrical expertise.</p><p>These businesses provided manufacturing depth and customers beyond the defense cycle.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>By 1985 Ferranti is identified principally with real-time computing, radar and defense electronics, industrial and scientific instruments, semiconductors, and power-system expertise. ICL carries much of the national general-purpose commercial-computer burden.</p><p>Ferranti remains a distinct British group; exact divisional boundaries and ownership are unsettled.</p>"}
    ],
    related:[...britishElectricalRelated,{href:"manchester.html",kicker:"Computing and industrial center",label:"Manchester"},{href:"international-computers-limited.html",kicker:"Commercial-computer successor",label:"International Computers Limited"},{href:"autocode.html",kicker:"Manchester software lineage",label:"Autocode"},{href:"reliability-engineering.html",kicker:"Systems discipline",label:"Reliability Engineering"}],
    facts:[["Founded","1883"],["Founder","Sebastian Ziani de Ferranti"],["Principal works","Hollinwood, Manchester"],["Commercial-computer milestone","Ferranti Mark 1 · 1951"],["Postwar fields","Computing · instruments · radar · power · semiconductors"],["Commercial-computer transfer","ICL settlement · 1967–1968"],["Later computing emphasis","Real-time and embedded systems"],["1985 status","Independent British engineering group"]],
    primarySources:[{href:"https://collection.sciencemuseumgroup.org.uk/people/ap11208/ferranti-international-plc",label:"Science Museum Group — Ferranti company history"},{href:"https://collection.sciencemuseumgroup.org.uk/people/ap9854/ferranti-sebastian-ziani-de",label:"Science Museum Group — Sebastian Ziani de Ferranti"}]
  }),

  "general-electric-company-britain": britishElectricalArticle({
    title:"General Electric Company",infoboxTitle:"The General Electric Company, plc",eyebrow:"Witton and Wembley · ‘Everything Electrical’ · 1886–1985",categories:["General Electric Company","British electrical industry","Birmingham","Power engineering","British electronics industry"],
    lead:"The General Electric Company is a British electrical and electronics group founded in 1886 by Hugo Hirst and Gustav Byng. Known through the slogan ‘Everything Electrical,’ it manufactures lamps, switchgear, generators, motors, domestic appliances, communications equipment, radar, industrial electronics, and atomic-power systems. The company’s Witton works and Wembley research laboratories connect Birmingham mass manufacture to national-grid and strategic research contracts.",
    canon:`<!-- altwwii-writer-block:start id=wb-g-20260816-br3c4 writer=g kind=revision created=2026-08-16T14:40:00-06:00 -->GEC's 1886 foundation, Hirst and Byng, Manchester and Witton works, Osram business, Wembley laboratories, national-grid work, and pre-divergence electrical range are inherited history.${britishElectricalHistory} GEC is fixed among Britain's principal 1947 electrical anchors and later among the important power, radar, electronics, aerospace, and computing firms.${britishElectricalCanon} Its exact postwar atomic work, acquisitions, divisions, leadership, plants, brands, output, independence from English Electric, and 1985 ownership remain compatible incorporated reconstruction or open; the real-world AEI and English Electric mergers are not inherited automatically.${britishElectricalExtrapolation}<!-- altwwii-writer-block:end -->`,
    sections:[
      {id:"origins",title:"Formation and early manufacture",html:"<p>Hugo Hirst and Gustav Byng established the General Electric Apparatus Company in 1886. The business became a private company in 1889 and a public company in 1900. Its first factory was in Manchester.</p><p>The large Witton works opened near Birmingham in 1902 and became the principal manufacturing center.</p>"},
      {id:"range",title:"‘Everything Electrical’",html:"<p>GEC used the slogan ‘Everything Electrical’ for a product range extending from Osram lamps and household fittings to motors, generators, switchgear, cables, instruments, and industrial plant. The breadth gave distributors, utilities, builders, factories, and households a common supplier.</p>"},
      {id:"grid",title:"National-grid engineering",html:"<p>Generators, transformers, switchgear, protection, measurement, lighting, and transmission equipment connected GEC to the development of the national grid. Utility orders created long production runs and stringent testing requirements.</p><p>Postwar repair and electrification renewed these markets before atomic stations added new control and safety work.</p>"},
      {id:"research",title:"Wembley laboratories",html:"<p>GEC opened industrial research laboratories at Wembley in 1923. Work in lamps, vacuum devices, radio, communications, materials, measurement, and electronics supplied both product divisions and public research programs.</p><p>The laboratories helped the company move from electrical manufacture into electronic systems.</p>"},
      {id:"war",title:"Radar and communications",html:"<p>Wartime work included radar, the cavity magnetron, communications equipment, components, and mass lighting. GEC plants supplied equipment at scales requiring coordinated inspection, subcontracting, and service documentation.</p><p>Radar and communications teams continued into air defense, broadcasting, navigation, and industrial electronics after 1947.</p>"},
      {id:"reconstruction",title:"Reconstruction and atomic power",html:"<p>Grid repair, housing electrification, factories, railways, appliances, lighting, and power stations sustained GEC during reconstruction. The <a href='british-atomic-power-programme.html'>British Atomic Power Programme</a> added control gear, electrical machines, instrumentation, and research contracts.</p><p>Domestic appliances made the company visible in households while heavy equipment remained its strategic foundation.</p>"},
      {id:"structure",title:"Corporate structure",html:"<p>In this setting GEC does not absorb English Electric into one national electrical conglomerate in 1968. The two firms compete and cooperate through public contracts, standards committees, research arrangements, and joint supply chains.</p><p>This preserves an alternative heavy-electrical and electronics center at the cost of duplicated capacity and divided capital.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>By 1985 GEC spans grid and power-station equipment, lighting, switchgear, appliances, radar, communications, industrial electronics, components, and atomic engineering. Its scale gives Britain a general electrical supplier alongside more specialized firms.</p><p>Exact later subsidiaries and acquisitions remain open.</p>"}
    ],
    related:[...britishElectricalRelated,{href:"birmingham.html",kicker:"Principal industrial region",label:"Birmingham"},{href:"british-atomic-power-programme.html",kicker:"Atomic customer",label:"British Atomic Power Programme"},{href:"english-electric.html",kicker:"Independent competitor",label:"English Electric"},{href:"material-culture.html",kicker:"Civilian market",label:"Material Culture and Civilian Industry"}],
    facts:[["Founded","1886"],["Founders","Hugo Hirst · Gustav Byng"],["Principal works","Witton, Birmingham · from 1902"],["Research center","Wembley laboratories · from 1923"],["Historic slogan","Everything Electrical"],["Principal fields","Grid · lighting · switchgear · electronics · appliances"],["Postwar strategic field","Atomic power and radar"],["1985 status","Independent of English Electric"]],
    primarySources:[{href:"https://collection.sciencemuseumgroup.org.uk/people/ap314",label:"Science Museum Group — General Electric Company history"},{href:"https://engx.theiet.org/b/blogs/posts/125_2d00_years_2d00_of_2d00_grantmaking",label:"Institution of Engineering and Technology — GEC and electrical-engineering philanthropy"}]
  }),

  "english-electric": britishElectricalArticle({
    title:"English Electric",infoboxTitle:"The English Electric Company Limited",eyebrow:"Stafford, Rugby, Preston, and Warton · power, traction, aircraft, and computing · 1918–1985",categories:["English Electric","British electrical industry","British aerospace companies","Computing in Britain","Rail transport in Britain"],
    lead:"The English Electric Company Limited is a British heavy-electrical, traction, aircraft, telecommunications, and computing group formed in 1918 from several major wartime manufacturers. Its works at Stafford, Rugby, Preston, Bradford, and Warton supply turbines, generators, transformers, locomotives, diesel engines, aircraft, radar, communications systems, and computers. The Canberra and Lightning aircraft and DEUCE computer are among its best-known postwar products.",
    canon:`<!-- altwwii-writer-block:start id=wb-g-20260816-br4d5 writer=g kind=revision created=2026-08-16T14:40:00-06:00 -->English Electric's 1918 formation, constituent businesses, Stafford, Rugby and Preston works, heavy-electrical and traction base, and other pre-divergence holdings are inherited history.${britishElectricalHistory} Its place among the principal 1947 electrical anchors, continuing power, radar, aerospace and computing work, and the 1967–68 transfer of English Electric Computers into ICL are established.${britishElectricalCanon} Exact postwar subsidiaries, aircraft and locomotive organization, Marconi relationship, contracts, continued corporate independence, and 1985 structure remain compatible incorporated reconstruction or open; the real-world merger into GEC is not inherited automatically.${britishElectricalExtrapolation}<!-- altwwii-writer-block:end -->`,
    sections:[
      {id:"formation",title:"Formation",html:"<p>English Electric was formed on 14 December 1918 around Dick, Kerr & Company of Preston, Willans & Robinson of Rugby, the Phoenix Dynamo Manufacturing Company of Bradford, and the Coventry Ordnance Works. The Siemens Brothers Dynamo Works at Stafford joined in 1919.</p><p>Stafford became the company headquarters in 1931.</p>"},
      {id:"power",title:"Power engineering",html:"<p>Turbines, turbo-generators, hydroelectric sets, transformers, switchgear, motors, and large electrical machines supplied utilities, factories, mines, shipyards, and export projects. Rugby and Stafford formed the core of this work.</p><p>Grid reconstruction and later nuclear stations sustained high-integrity manufacturing and installation teams.</p>"},
      {id:"traction",title:"Railway and diesel traction",html:"<p>English Electric supplied electrical equipment for locomotives, suburban systems, and industrial traction. Napier joined the group in 1942. The Vulcan Foundry and Robert Stephenson & Hawthorns entered the organization in 1955, broadening complete locomotive and diesel capability.</p><p>Commonwealth railways provided export and long-term maintenance work.</p>"},
      {id:"communications",title:"Marconi and communications",html:"<p>The Marconi Company joined English Electric in 1946. Radio, radar, broadcasting, naval communications, microwave links, and later satellite-ground equipment connected the group’s electrical and electronics divisions.</p><p>Marconi retained a recognizable identity within the wider group.</p>"},
      {id:"aircraft",title:"Aircraft",html:"<p>English Electric’s Warton organization developed the <a href='canberra-b2.html'>Canberra</a> jet bomber and reconnaissance aircraft and the <a href='lightning-f3.html'>Lightning</a> interceptor. Aircraft design required engines, radar, instruments, control systems, electrical generation, testing, and production management across the group.</p><p>Later aircraft work entered national industrial arrangements while the English Electric name remained attached to the lineage.</p>"},
      {id:"computers",title:"Computers",html:"<p>English Electric manufactured DEUCE from the National Physical Laboratory’s ACE lineage and developed additional scientific and commercial systems. Power engineering, aircraft calculation, radar, and industrial control provided demanding internal customers.</p><p>English Electric Computers entered <a href='international-computers-limited.html'>ICL</a> through the 1967–1968 procurement consolidation. Specialized control and electronic work remained elsewhere in the group.</p>"},
      {id:"structure",title:"Independent group",html:"<p>English Electric remains independent of GEC in the setting’s postwar structure. It works through joint standards, government contracts, the <a href='british-aircraft-corporation.html'>British Aircraft Corporation</a>, ICL, and Commonwealth projects instead of disappearing into one electrical holding company.</p><p>The arrangement preserves distinct design offices and regional works.</p>"},
      englishElectricAircraftListSection([
        ["English Electric A.1","Canberra B.2","canberra-b2.html","a"],
        ["English Electric P.1B","Lightning F.3","lightning-f3.html","a"]
      ]),
      {id:"position",title:"Position in 1985",html:"<p>By 1985 English Electric remains a heavy-engineering and systems group centered on power, traction, telecommunications, aerospace heritage, large machinery, control, and Commonwealth service. Marconi supplies much of its public electronics identity.</p><p>Detailed divisional boundaries and later corporate purchases remain open.</p>"}
    ],
    related:[...britishElectricalRelated,{href:"general-electric-company-britain.html",kicker:"Heavy-electrical competitor",label:"General Electric Company"},{href:"international-computers-limited.html",kicker:"Computer successor",label:"International Computers Limited"},{href:"canberra-b2.html",kicker:"Jet bomber lineage",label:"Canberra B.2"},{href:"lightning-f3.html",kicker:"Interceptor lineage",label:"Lightning F.3"}],
    facts:[["Formed","14 December 1918"],["Headquarters","Stafford · from 1931"],["Principal works","Stafford · Rugby · Preston · Warton"],["Communications subsidiary","Marconi · from 1946"],["Computer lineage","DEUCE · English Electric Computers"],["Aircraft lineages","Canberra · Lightning"],["Commercial-computer transfer","ICL settlement · 1967–1968"],["1985 status","Independent of GEC"]],
    primarySources:[{href:"https://collection.sciencemuseumgroup.org.uk/people/ap183/english-electric-company-limited",label:"Science Museum Group — English Electric company history"},{href:"https://www.baesystems.com/heritage/page/english-electric-canberra",label:"BAE Systems Heritage — English Electric Canberra"}]
  }),

  "pye": britishElectricalArticle({
    title:"Pye",infoboxTitle:"Pye Limited",eyebrow:"Cambridge · radio, television, mobile communications, and instruments · 1896–1985",categories:["Pye","British electronics industry","Cambridge","Radio in Britain","Television in Britain"],
    lead:"Pye Limited is a Cambridge electronics company founded by William George Pye in 1896. Scientific instruments lead into radio receivers, television sets and cameras, broadcast transmitters, industrial electronics, two-way mobile radio, components, and medical equipment. Its factories and laboratories make Cambridge a consumer and communications-electronics center alongside the university’s computing institutions.",
    canon:`<!-- altwwii-writer-block:start id=wb-g-20260816-br5e6 writer=g kind=revision created=2026-08-16T14:40:00-06:00 -->Pye's 1896 foundation, scientific-instrument origin, 1925 radio entry, C. O. Stanley's pre-divergence control, and Cambridge radio and television work are inherited history.${britishElectricalHistory} Pye is fixed among Britain's principal 1947 electrical anchors and remains important in later television and consumer electronics.${britishElectricalCanon} Its post-divergence mobile-radio, medical, printed-circuit, product, subsidiary, site, market-share, Philips-control, and 1985 ownership chronology remains compatible incorporated reconstruction or open.${britishElectricalExtrapolation}<!-- altwwii-writer-block:end -->`,
    sections:[
      {id:"origins",title:"Scientific-instrument origins",html:"<p>William George Pye founded the business in Cambridge in 1896 to make scientific instruments. University laboratories and technical customers supplied an early market for precise electrical and physical apparatus.</p><p>The company entered radio manufacture in 1925.</p>"},
      {id:"stanley",title:"Expansion under C. O. Stanley",html:"<p>C. O. Stanley acquired control in 1928. Pye Radio was organized in 1929, and the broader company adopted the Pye Limited title in 1937.</p><p>Receiver production, advertising, dealers, components, and factory expansion turned an instrument maker into a mass electronics concern.</p>"},
      {id:"war",title:"Radar and communications",html:"<p>Radar, radio, communications, valves, instruments, and military production expanded during the long war. The resulting laboratories, skilled workforce, and test equipment supported civil radio, television, and mobile communications after 1947.</p>"},
      {id:"radio",title:"Radio and household electronics",html:"<p>Pye radios served the reconstruction market from mains and battery sets through increasingly compact valve and transistor receivers. By the late 1950s the company was a principal British participant in transistor radio.</p><p>Audio equipment and appliances extended the consumer range through dealers and Commonwealth distributors.</p>"},
      {id:"television",title:"Television and broadcasting",html:"<p>Pye manufactured television receivers, studio and outside-broadcast equipment, cameras, transmitters, and professional links. The firm supplied both the domestic set and parts of the broadcasting system that produced and distributed the picture.</p><p>Printed-circuit adoption in 1956 and specialized television-transmission organization from 1960 supported industrial-scale production and export.</p>"},
      {id:"mobile",title:"Two-way and mobile radio",html:"<p>Pye Telecommunications supplied police, fire, ambulance, utility, transport, industrial, colonial, and military customers. Base stations, vehicle sets, handheld equipment, antennas, dispatch systems, installation, and maintenance formed one service field.</p><p>Commonwealth agencies valued rugged equipment and continuing parts support.</p>"},
      {id:"instruments",title:"Industrial, medical, and scientific equipment",html:"<p>The company retained instrument, component, medical, and industrial-electronics divisions alongside household products. Test equipment, process controls, laboratory apparatus, and specialized imaging broadened demand beyond the consumer cycle.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>By 1985 Pye remains a Cambridge-centered British electronics group associated with radio, television, mobile communications, broadcast transmitters, instruments, and technical service. It faces intense Japanese competition in mass consumer goods while retaining professional and public-service markets.</p><p>Ownership and final brand structure remain unsettled.</p>"}
    ],
    related:[...britishElectricalRelated,{href:"cambridge.html",kicker:"Company city",label:"Cambridge"},{href:"emi.html",kicker:"Broadcasting and consumer counterpart",label:"EMI"},{href:"consumer-telecommunications.html",kicker:"Communications market",label:"Consumer Telecommunications"},{href:"instrumented-modernity.html",kicker:"Civilian period",label:"Instrumented Modernity"}],
    facts:[["Founded","1896"],["Founder","William George Pye"],["Headquarters and principal center","Cambridge"],["Entered radio manufacture","1925"],["Controlling figure from 1928","C. O. Stanley"],["Principal fields","Radio · television · mobile communications · instruments"],["Printed-circuit production","From 1956"],["1985 status","Continuing British electronics group"]],
    primarySources:[{href:"https://collection.sciencemuseumgroup.org.uk/people/ap8277/pye-ltd",label:"Science Museum Group — Pye company history"},{href:"https://www.museumoftechnology.com/pye-museum-cmt",label:"Cambridge Museum of Technology — Pye collection and company history"}]
  }),

  "emi": britishElectricalArticle({
    title:"EMI",infoboxTitle:"Electric and Musical Industries Limited",eyebrow:"Hayes and London · recording, television, electronics, and scientific imaging · 1931–1985",categories:["EMI","British electronics industry","Music industry in Britain","Television in Britain","Medical technology"],
    lead:"Electric and Musical Industries Limited, generally known as EMI, is a British recording, broadcasting, consumer-electronics, and scientific-technology group formed in 1931 by the merger of the Gramophone Company and Columbia Graphophone Company. Its record labels, studios, pressing works, electrical recording, stereophony, television systems, radar work, electronics laboratories, and medical imaging place recorded culture and advanced engineering inside one corporate institution.",
    canon:`<!-- altwwii-writer-block:start id=wb-g-20260816-br6f7 writer=g kind=revision created=2026-08-16T14:40:00-06:00 -->EMI's 1931 formation, Gramophone and Columbia lineages, Hayes base, recording business, and Blumlein-era stereophony, television, and radar work are inherited history.${britishElectricalHistory} EMI's later importance in television, recording, and consumer electronics is established.${britishElectricalCanon} EMI Electronics, business-computer and transistorized-machine dates, television-camera and computed-tomography development, labels, acquisitions, studios, imaging rollout, Thorn relationship, and 1985 ownership remain compatible incorporated reconstruction or open rather than inherited history.${britishElectricalExtrapolation}<!-- altwwii-writer-block:end -->`,
    sections:[
      {id:"formation",title:"Formation in 1931",html:"<p>EMI was formed in 1931 by the merger of the Gramophone Company and Columbia Graphophone Company. The combined business inherited record labels, artists, catalogues, pressing plants, recording engineers, distribution, and consumer apparatus.</p><p>Hayes in Middlesex became the principal manufacturing and research center.</p>"},
      {id:"recording",title:"Recording and stereophony",html:"<p>Electrical recording, microphones, disc mastering, pressing, reproduction equipment, studios, and catalogues connected EMI’s technical and cultural businesses. Engineer Alan Blumlein patented a practical stereophonic recording and reproduction system in 1931.</p><p>Recording research continued through improved discs, magnetic tape, high fidelity, stereo, and studio electronics.</p>"},
      {id:"television",title:"Television",html:"<p>EMI and Marconi television work was combined in 1934 as Marconi–EMI Television. Electronic cameras and the 405-line system contributed to the BBC television service before the war.</p><p>Postwar cameras, studio chains, outside-broadcast equipment, transmitters, and receivers supplied the expansion of British and Commonwealth television.</p>"},
      {id:"war",title:"Wartime electronics",html:"<p>EMI concentrated on specialized thermionic valves, radar equipment, guided systems, communications, and production research during the long war. Alan Blumlein died in 1942 while testing airborne radar.</p><p>Wartime laboratories and manufacturing methods survived into civil broadcasting, computers, and scientific instruments.</p>"},
      {id:"electronics",title:"EMI Electronics",html:"<p>EMI Electronics Limited was formed in 1955 to expand commercial and industrial electronics. The subsidiary developed the EMI Electronic Business Machine in 1957 and a transistorized computer in 1958, then delivered television cameras to British broadcasters.</p><p>General-purpose computer work later entered the wider British consolidation while specialized electronic and scientific systems remained with EMI.</p>"},
      {id:"music",title:"Music, labels, and distribution",html:"<p>EMI records, publishes, presses, markets, and distributes music through a collection of labels and territorial organizations. Classical, popular, regional, and Commonwealth catalogues create both cultural prestige and recurring commercial revenue.</p><p>Studios, recording equipment, rights administration, shops, broadcasting, and export offices form a system broader than record manufacture.</p>"},
      {id:"imaging",title:"Scientific and medical imaging",html:"<p>Godfrey Hounsfield’s work at EMI laboratories produced computed-tomography scanning in the early 1970s. Detectors, X-ray systems, computation, reconstruction algorithms, displays, and hospital practice were combined into a new medical instrument.</p><p>Scientific imaging gave the electronics division a high-value field distinct from mass entertainment equipment.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>By 1985 EMI remains a British group joining recorded music, publishing and distribution, professional broadcasting, studio technology, electronics, and scientific imaging. Its cultural catalogue and engineering laboratories operate on different commercial cycles.</p><p>The setting does not presently establish a Thorn–EMI merger; exact corporate form and later ownership remain open.</p>"}
    ],
    related:[...britishElectricalRelated,{href:"pye.html",kicker:"Broadcasting counterpart",label:"Pye"},{href:"computing.html",kicker:"Electronic field",label:"Computing"},{href:"consumer-telecommunications.html",kicker:"Household systems",label:"Consumer Telecommunications"},{href:"material-culture.html",kicker:"Civilian setting",label:"Material Culture and Civilian Industry"}],
    facts:[["Formed","1931"],["Predecessors","Gramophone Company · Columbia Graphophone Company"],["Principal works","Hayes, Middlesex"],["Early technical distinction","Stereophonic recording · electronic television"],["Television organization","Marconi–EMI Television · from 1934"],["Industrial subsidiary","EMI Electronics · from 1955"],["Medical milestone","Computed tomography · early 1970s"],["1985 status","Independent British recording and electronics group"]],
    primarySources:[{href:"https://collection.sciencemuseumgroup.org.uk/people/cp39349/electric-and-musical-industries-limited",label:"Science Museum Group — Electric and Musical Industries history"},{href:"https://collection.sciencemuseumgroup.org.uk/people/cp1239",label:"Science Museum Group — EMI Electronics history"},{href:"https://www.emiarchivetrust.org/inventor-of-stereo-sound-alan-dower-blumleins-world-changing-1931-patent-celebrated-as-part-of-the-uk-governments-great-for-imagination-campaign/",label:"EMI Archive Trust — Alan Blumlein’s stereo, television, and radar work"}]
  }),

  "international-computers-limited": britishElectricalArticle({
    title:"International Computers Limited",eyebrow:"Commonwealth commercial-computer group · from 1968",infoboxKicker:"British computer manufacturer",categories:["International Computers Limited","Computing in Britain","British electrical industry","Commonwealth technology","Computer companies"],
    lead:"International Computers Limited, usually abbreviated ICL, is the British commercial-computer group formed in 1968 from International Computers and Tabulators, English Electric Computers, and selected Elliott, LEO, Marconi, and Ferranti operations. It supplies mainframes, operating systems, terminals, bureau services, government data processing, business systems, and Commonwealth support while universities and parent engineering firms retain separate scientific, real-time, and specialized computing lines.",
    canon:`<!-- altwwii-writer-block:start id=wb-g-20260816-br7g8 writer=g kind=revision created=2026-08-16T14:40:00-06:00 -->The pre-divergence punched-card and computing lineages inherited by ICL's constituent firms remain inherited history.${britishElectricalHistory} Government and Commonwealth procurement bringing ICT, English Electric Computers, Ferranti commercial computing, and selected Elliott and LEO interests into ICL around 1967–68 is established; ICL is the production and export champion rather than the owner of all British computer science.${britishElectricalCanon} Exact equity, statutes, Marconi participation, inherited product families, sites, service network, later roadmap, workforce, acquisitions, and 1985 finances remain compatible incorporated reconstruction or open.${britishElectricalExtrapolation}<!-- altwwii-writer-block:end -->`,
    sections:[
      {id:"predecessors",title:"Predecessor companies",html:"<p>International Computers and Tabulators was formed in 1959 from the British Tabulating Machine Company and Powers-Samas. It inherited punched-card equipment, accounting-machine customers, service engineers, and the 1200 and 1300 computer families.</p><p>ICT acquired Ferranti’s business-computer division in 1963. English Electric’s computer organization combined DEUCE and later systems with LEO business computing, Marconi electronics, and selected Elliott work.</p>"},
      {id:"formation",title:"Formation in 1968",html:"<p>The government brought ICT and English Electric Computers together in 1968 as ICL. The arrangement followed procurement decisions made during 1967–1968 and incorporated selected Elliott, LEO, Marconi, and Ferranti commercial interests.</p><p>The purpose was to create an order base large enough to sustain a compatible British mainframe family and its software.</p>"},
      {id:"boundary",title:"Limits of the consolidation",html:"<p>ICL did not absorb every British computer activity. Universities retained independent research. <a href='ferranti.html'>Ferranti</a> continued real-time, military, instrument, and semiconductor systems; <a href='english-electric.html'>English Electric</a> and Marconi retained other control and communications work; classified establishments maintained separate machines.</p><p>The consolidation applied principally to general-purpose commercial and administrative computing.</p>"},
      {id:"products",title:"Systems and software",html:"<p>ICL developed compatible mainframe systems from the inherited ICT 1900, English Electric, and LEO customer bases. Operating systems, compilers, databases, transaction processing, terminals, communications, peripherals, and conversion tools became as important as processor hardware.</p><p>Backward compatibility and migration contracts protected users whose records and programs represented years of work.</p>"},
      {id:"customers",title:"Government and commercial customers",html:"<p>Revenue came from tax, social administration, defense, the Post Office, banks, insurers, manufacturers, retailers, universities, public corporations, and Commonwealth governments. <a href='j-lyons.html'>J. Lyons</a> supplied a distinctive tradition of payroll, inventory, scheduling, and business-systems analysis.</p><p>Large public orders supported development and also exposed the company to changes in government purchasing.</p>"},
      {id:"geography",title:"Works and service network",html:"<p>Bracknell served as a major administrative and development center. Letchworth, Manchester, the Midlands, and other inherited sites supported manufacture, software, testing, and maintenance.</p><p>Overseas offices and Commonwealth service depots supplied installation, operator training, field engineers, spares, software support, and data conversion.</p>"},
      {id:"commonwealth",title:"Commonwealth computing system",html:"<p>ICL participated in <a href='commonwealth-programming-languages.html'>Commonwealth language</a>, library, standards, and packet-network work without imposing one machine on every member. Gateways and translation tools connected ICL installations to ACE, EDSAC, Ferranti, North American, and Dominion systems.</p><p>Procurement preferences created a protected home system rather than technical isolation.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>By 1985 ICL is Britain’s principal general-purpose computer manufacturer and systems supplier. Mainframes and institutional services remain its foundation as smaller business computers, terminals, networks, and personal machines expand.</p><p>The company competes with IBM, American rivals, continental systems, and Japanese suppliers while relying on a durable British and Commonwealth public-sector base.</p>"}
    ],
    related:[...britishElectricalRelated,{href:"ferranti.html",kicker:"Commercial-computer predecessor",label:"Ferranti"},{href:"english-electric.html",kicker:"Computer predecessor",label:"English Electric"},{href:"j-lyons.html",kicker:"LEO business-computing lineage",label:"J. Lyons and Co."},{href:"commonwealth-programming-languages.html",kicker:"Software system",label:"Commonwealth Programming Languages"}],
    facts:[["Formed","1968"],["Principal predecessors","ICT · English Electric Computers"],["Additional lineages","Ferranti · Elliott · LEO · Marconi"],["Principal field","General-purpose commercial and administrative computing"],["Major customers","Government · Post Office · finance · industry · Commonwealth"],["Main locations","Bracknell · Letchworth · Manchester · Midlands"],["Protected market","British and Commonwealth public procurement"],["1985 status","Principal British computer manufacturer"]],
    primarySources:[{href:"https://collection.sciencemuseumgroup.org.uk/people/ap28239/international-computers-limited",label:"Science Museum Group — International Computers Limited history"},{href:"https://collection.sciencemuseumgroup.org.uk/people/ap13056/international-computers-and-tabulators",label:"Science Museum Group — International Computers and Tabulators history"},{href:"https://collection.sciencemuseumgroup.org.uk/documents/aa110069601/archive-of-international-computers-ltd",label:"Science Museum Group — Archive of International Computers Limited"}]
  })
});
